use std::process::Command;
use std::os::unix::ffi::OsStrExt;
use std::ffi::OsStr;

fn run(b:&[u8])->Vec<u8>{
    let o=Command::new("/workspace/dataset/test4_executable").arg(OsStr::from_bytes(b)).output().unwrap();
    o.stdout.split(|c|*c==b'\n').filter(|l|!l.is_empty()).map(|l|l[0]).collect()
}
fn main(){
    let mut seed:u64=0x12345678;
    let mut rnd=||{seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;seed};
    let mut fails=0; let mut n=0;
    for _ in 0..4000{
        let len=(rnd()%80) as usize;
        let mut v=Vec::with_capacity(len);
        for _ in 0..len{
            let mut c=(rnd()%255+1) as u8; // 1..255, no NUL
            if c==0 {c=1;}
            v.push(c);
        }
        let r=run(&v); n+=1;
        let exp = if len>=1 && len<=63 {b'1'} else {b'0'};
        if r.len()<2 || r[1]!=exp {
            fails+=1;
            if fails<=10 {
                println!("COUNTEREXAMPLE len={} exp={} got={} bytes={:02x?}",len,exp as char,r.get(1).map(|c|*c as char).unwrap_or('?'),v);
            }
        }
    }
    println!("random fuzz: {} runs, {} counterexamples",n,fails);
}
