use std::process::Command; use std::os::unix::ffi::OsStrExt; use std::ffi::OsStr;
fn line2(b:&[u8])->u8{
    let o=Command::new("/workspace/dataset/test4_executable").arg(OsStr::from_bytes(b)).output().unwrap();
    let ls:Vec<&[u8]>=o.stdout.split(|c|*c==b'\n').filter(|l|!l.is_empty()).collect();
    if ls.len()<2 {return b'?'} ls[1][0]
}
fn main(){
 let mut seed:u64=0xa5a5f00d;
 let mut rnd=move||{seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;seed};
 let mut fails=0u32; let mut n=0u32;
 // A: well-formed UTF-8 only, exact byte lengths 55..=72
 for target in 55usize..=72{
   for _ in 0..300{
     let mut v:Vec<u8>=Vec::new();
     while v.len()<target{
        let pick=rnd()%4;
        let ch=match pick{0=>char::from_u32(0x61+(rnd()%26)as u32).unwrap(),
                          1=>char::from_u32(0xC0+(rnd()%300)as u32).unwrap(),
                          2=>char::from_u32(0x4E00+(rnd()%2000)as u32).unwrap(),
                          _=>char::from_u32(0x1F300+(rnd()%200)as u32).unwrap()};
        let mut buf=[0u8;4]; let s=ch.encode_utf8(&mut buf);
        if v.len()+s.len()>target {break}
        v.extend_from_slice(s.as_bytes());
     }
     while v.len()<target{v.push(b'a');}
     let r=line2(&v); n+=1;
     let exp=if v.len()<=63{b'1'}else{b'0'};
     if r!=exp{fails+=1; if fails<=15{println!("CE utf8 len={} exp={} got={} hex={:02x?}",v.len(),exp as char,r as char,v);}}
   }
 }
 // B: wide long lengths 64..3000 random ascii
 for _ in 0..1200{
   let len=64+(rnd()as usize)%2937;
   let v=vec![b'z';len]; let r=line2(&v); n+=1;
   if r!=b'0'{fails+=1; println!("CE long len={} got={}",len,r as char);}
 }
 println!("utf8+long fuzz: {} runs, {} counterexamples",n,fails);
}
